import React, { useState } from 'react';
import { 
  LayoutDashboard, Truck, History, Users, Radio, 
  Zap, Target, Database, Map, Calendar, 
  Star, LineChart, HardHat, FileText 
} from 'lucide-react';

// --- IMPORT YOUR SEPARATE TAB FILES ---
import BinMonitoringTab from '../tabs/BinMonitoringTab';
import ZonesTab from '../tabs/ZonesTab';
import ScheduleTab from '../tabs/ScheduleTab';
import PointsTab from '../tabs/PointsTab';
import AnalyticsTab from '../tabs/AnalyticsTab';
import CitizensTab from '../tabs/CitizensTab';
import WorkersTab from '../tabs/WorkersTab';
import ReportsTab from '../tabs/ReportsTab';

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState('BINS');

  // THE 8 TABS YOU REQUESTED
  const navItems = [
    { id: 'BINS', icon: <Truck />, label: 'BIN_MONITOR' },
    { id: 'ZONES', icon: <Map />, label: 'AREAS_ZONES' },
    { id: 'SCHEDULE', icon: <Calendar />, label: 'COLL_SCHED' },
    { id: 'POINTS', icon: <Star />, label: 'REWARDS' },
    { id: 'ANALYTICS', icon: <LineChart />, label: 'ANALYTICS' },
    { id: 'CITIZENS', icon: <Users />, label: 'CITIZENS' },
    { id: 'WORKERS', icon: <HardHat />, label: 'WORKERS' },
    { id: 'REPORTS', icon: <FileText />, label: 'REPORTS' },
  ];

  return (
    <div className="w-full max-w-[1300px] min-h-screen flex flex-col items-center justify-center p-6 animate-slot relative">

      {/* --- THE OUTER CHASSIS (Heavy Red Frame) --- */}
      <div className="w-full bg-[#AB1717] border-[10px] border-[#47510B] rounded-[60px] p-8 red-stack-shadow relative flex flex-col gap-6 shadow-[20px_20px_0_0_#47510B]">

        {/* TOP STATUS LIGHTS & BRANDING */}
        <div className="flex justify-between items-center px-4 shrink-0">
          <div className="flex gap-2">
            {[1, 2, 3].map(i => (
              <div key={i} className="w-6 h-2 bg-[#CAD23C] rounded-full border-2 border-[#47510B] animate-pulse" style={{ animationDelay: `${i * 0.2}s` }} />
            ))}
          </div>
          <h1 className="text-4xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
            TRASH<span className="text-[#CAD23C]">2</span>TRACK
          </h1>
          <div className="text-[10px] font-black text-[#FDFAD8] bg-[#47510B] px-4 py-1 rounded-full border-2 border-[#CAD23C]">
            OS_VERSION: 3.0.1_ADMIN
          </div>
        </div>

        {/* --- THE CENTRAL MONITOR (Blue-Grey Area) --- */}
        <div className="relative h-[550px] bg-[#A1AED1] border-[8px] border-[#47510B] rounded-[40px] panel-inset-shadow overflow-hidden flex flex-col">
          {/* Scanning Grid Overlay */}
          <div className="absolute inset-0 opacity-10 pointer-events-none" 
               style={{ backgroundImage: 'radial-gradient(#47510B 1.5px, transparent 1.5px)', backgroundSize: '30px 30px' }} />

          {/* DYNAMIC CONTENT SCREEN */}
          <div className="relative z-10 p-6 h-full flex flex-col overflow-y-auto no-scrollbar">

            {/* Header of the Screen */}
            <div className="flex justify-between items-center mb-4 shrink-0 border-b-4 border-[#47510B]/10 pb-2">
              <div className="bg-[#47510B] text-[#CAD23C] px-4 py-1.5 rounded-lg font-mono text-[10px] border-2 border-[#FDFAD8]/20">
                MODULE_ACTIVE: {activeTab}
              </div>
              <div className="flex items-center gap-4">
                <span className="text-[#47510B] font-black text-[10px] uppercase tracking-widest animate-pulse">System_Linked</span>
                <div className="flex gap-1">
                  {[1, 2, 3, 4, 5].map(i => <div key={i} className="w-1.5 h-4 bg-[#AB1717] border border-[#47510B]" />)}
                </div>
              </div>
            </div>

            {/* TAB CONTENT DISPATCHER */}
            <div className="flex-grow animate-slot">
              {activeTab === 'BINS' && <BinMonitoringTab />}
              {activeTab === 'ZONES' && <ZonesTab />}
              {activeTab === 'SCHEDULE' && <ScheduleTab />}
              {activeTab === 'POINTS' && <PointsTab />}
              {activeTab === 'ANALYTICS' && <AnalyticsTab />}
              {activeTab === 'CITIZENS' && <CitizensTab />}
              {activeTab === 'WORKERS' && <WorkersTab />}
              {activeTab === 'REPORTS' && <ReportsTab />}
            </div>
          </div>
        </div>

        {/* --- THE SELECTOR CONSOLE (Bottom Tabs - 2 Rows of 4) --- */}
        <div className="grid grid-cols-4 gap-3 px-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`
                relative h-20 rounded-2xl border-[5px] border-[#47510B] transition-all flex flex-col items-center justify-center gap-1
                ${activeTab === item.id 
                  ? 'bg-[#CAD23C] translate-y-1 shadow-none' 
                  : 'bg-[#FDFAD8] -translate-y-1 shadow-[0_6px_0_0_#47510B] hover:-translate-y-2'}
              `}
            >
              <div className={`${activeTab === item.id ? 'text-[#47510B]' : 'text-[#AB1717]'} scale-75 md:scale-100`}>
                {item.icon}
              </div>
              <span className={`text-[8px] font-[1000] uppercase tracking-tighter ${activeTab === item.id ? 'text-[#47510B]' : 'text-[#AB1717]'}`}>
                {item.label}
              </span>
              <div className={`absolute top-1.5 right-1.5 w-1.5 h-1.5 rounded-full border border-[#47510B] ${activeTab === item.id ? 'bg-[#AB1717] animate-pulse' : 'bg-[#47510B]'}`} />
            </button>
          ))}
        </div>

        {/* DECORATIVE BOLTS */}
        <div className="absolute top-4 left-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
        <div className="absolute top-4 right-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
        <div className="absolute bottom-4 left-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
        <div className="absolute bottom-4 right-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
      </div>

      {/* SYSTEM TAG */}
      <div className="mt-6 flex gap-6 items-center opacity-40">
        <Zap size={16} className="text-[#AB1717]" />
        <p className="text-[9px] font-black uppercase tracking-[0.5em] text-[#47510B]">Secure_Admin_Terminal_Trash2Track</p>
        <Database size={16} className="text-[#AB1717]" />
      </div>
    </div>
  );
};

export default Dashboard;
